CREATE VIEW public.v_ayuda AS
 SELECT unnest(ARRAY['1. SELECT * FROM v_resumen;                              -- Ver tablas con descripcion y cantidad de registros'::text, '2. SELECT * FROM v_documentacion WHERE tabla = ''persona''; -- Ver columnas, tipos y descripcion de una tabla'::text, '3. SELECT * FROM v_relaciones;                            -- Ver todas las foreign keys entre tablas'::text, '4. SELECT * FROM v_estadisticas;                          -- Ver registros por tabla'::text, '5. \dt+                                                   -- Ver tablas con descripcion (psql)'::text, '6. \d+ nombre_tabla                                       -- Ver columnas con descripcion (psql)'::text]) AS "Comandos disponibles para explorar la base de datos";


