--
-- Name: v_documentacion; Type: VIEW; Schema: public; Owner: clinica_user
--

CREATE VIEW public.v_documentacion AS
 SELECT t.table_name AS tabla,
    COALESCE((c.column_name)::name, '-'::name) AS columna,
    COALESCE((upper((c.data_type)::text) ||
        CASE
            WHEN (c.character_maximum_length IS NOT NULL) THEN (('('::text || c.character_maximum_length) || ')'::text)
            ELSE ''::text
        END), ''::text) AS tipo,
        CASE
            WHEN ((c.is_nullable)::text = 'NO'::text) THEN 'NO'::text
            ELSE 'SI'::text
        END AS nullable,
        CASE
            WHEN (pk.column_name IS NOT NULL) THEN 'PK'::text
            WHEN (fk.column_name IS NOT NULL) THEN ('FK -> '::text || (fk.ref_table)::text)
            ELSE ''::text
        END AS clave,
    COALESCE(col_description(cls.oid, (c.ordinal_position)::integer), obj_description(cls.oid, 'pg_class'::name), ''::text) AS descripcion
   FROM ((((information_schema.tables t
     JOIN pg_class cls ON ((cls.relname = (t.table_name)::name)))
     LEFT JOIN information_schema.columns c ON ((((c.table_name)::name = (t.table_name)::name) AND ((c.table_schema)::name = (t.table_schema)::name))))
     LEFT JOIN ( SELECT kcu.table_name,
            kcu.column_name
           FROM (information_schema.table_constraints tc
             JOIN information_schema.key_column_usage kcu ON (((tc.constraint_name)::name = (kcu.constraint_name)::name)))
          WHERE ((tc.constraint_type)::text = 'PRIMARY KEY'::text)) pk ON ((((pk.table_name)::name = (c.table_name)::name) AND ((pk.column_name)::name = (c.column_name)::name))))
     LEFT JOIN ( SELECT kcu.table_name,
            kcu.column_name,
            ccu.table_name AS ref_table
           FROM ((information_schema.table_constraints tc
             JOIN information_schema.key_column_usage kcu ON (((tc.constraint_name)::name = (kcu.constraint_name)::name)))
             JOIN information_schema.constraint_column_usage ccu ON (((tc.constraint_name)::name = (ccu.constraint_name)::name)))
          WHERE ((tc.constraint_type)::text = 'FOREIGN KEY'::text)) fk ON ((((fk.table_name)::name = (c.table_name)::name) AND ((fk.column_name)::name = (c.column_name)::name))))
  WHERE (((t.table_schema)::name = 'public'::name) AND ((t.table_type)::text = 'BASE TABLE'::text))
  ORDER BY t.table_name, c.ordinal_position;


ALTER VIEW public.v_documentacion OWNER TO clinica_user;

--
-- Name: VIEW v_documentacion; Type: COMMENT; Schema: public; Owner: clinica_user
--

COMMENT ON VIEW public.v_documentacion IS 'Detalle de cada columna: tipo, nullable, clave y descripcion. Filtrar con WHERE tabla = ''nombre''';


--
-- Name: v_estadisticas; Type: VIEW; Schema: public; Owner: clinica_user
--

CREATE VIEW public.v_estadisticas AS
 SELECT relname AS tabla,
    obj_description(oid, 'pg_class'::name) AS descripcion,
    (reltuples)::bigint AS registros_aprox
   FROM pg_class
  WHERE ((relkind = 'r'::"char") AND (relnamespace = ('public'::regnamespace)::oid))
  ORDER BY relname;


ALTER VIEW public.v_estadisticas OWNER TO clinica_user;

--
-- Name: VIEW v_estadisticas; Type: COMMENT; Schema: public; Owner: clinica_user
--

COMMENT ON VIEW public.v_estadisticas IS 'Conteo aproximado de registros por tabla';


--
-- Name: v_relaciones; Type: VIEW; Schema: public; Owner: clinica_user
--

CREATE VIEW public.v_relaciones AS
 SELECT con.conname AS restriccion,
    ((con.conrelid)::regclass)::text AS tabla_origen,
    a_orig.attname AS columna_origen,
    ((con.confrelid)::regclass)::text AS tabla_destino,
    a_dest.attname AS columna_destino,
    COALESCE(d.description, ''::text) AS descripcion
   FROM (((pg_constraint con
     JOIN pg_attribute a_orig ON (((a_orig.attnum = ANY (con.conkey)) AND (a_orig.attrelid = con.conrelid))))
     JOIN pg_attribute a_dest ON (((a_dest.attnum = ANY (con.confkey)) AND (a_dest.attrelid = con.confrelid))))
     LEFT JOIN pg_description d ON ((d.objoid = con.oid)))
  WHERE (con.contype = 'f'::"char")
  ORDER BY ((con.conrelid)::regclass)::text, con.conname;


ALTER VIEW public.v_relaciones OWNER TO clinica_user;

--
-- Name: VIEW v_relaciones; Type: COMMENT; Schema: public; Owner: clinica_user
--

COMMENT ON VIEW public.v_relaciones IS 'Mapa de foreign keys: tabla origen, columna, tabla destino y descripcion';


--
-- Name: v_resumen; Type: VIEW; Schema: public; Owner: clinica_user
--

CREATE VIEW public.v_resumen AS
 SELECT t.table_name AS tabla,
    obj_description(cls.oid, 'pg_class'::name) AS descripcion,
    (count(c.column_name))::integer AS columnas,
    (cls.reltuples)::bigint AS registros_aprox
   FROM ((information_schema.tables t
     JOIN pg_class cls ON (((cls.relname = (t.table_name)::name) AND (cls.relnamespace = ('public'::regnamespace)::oid))))
     LEFT JOIN information_schema.columns c ON ((((c.table_name)::name = (t.table_name)::name) AND ((c.table_schema)::name = (t.table_schema)::name))))
  WHERE (((t.table_schema)::name = 'public'::name) AND ((t.table_type)::text = 'BASE TABLE'::text))
  GROUP BY t.table_name, cls.oid, cls.reltuples
  ORDER BY t.table_name;


ALTER VIEW public.v_resumen OWNER TO clinica_user;

